import json,pathlib,hashlib
R=pathlib.Path(__file__).resolve().parent;P=R.parent/'workspace'
def load(n):return json.loads((R/n).read_text())
def save(n,x):(R/n).write_text(json.dumps(x,indent=2)+'\n')
old=load('initial-package-hashes.json');now={str(p.relative_to(P)):hashlib.sha256(p.read_bytes()).hexdigest() for p in P.rglob('*') if p.is_file()};assert old==now
save('package-integrity.json',{'unchanged':True,'files_checked':len(now),'before':'initial-package-hashes.json','after':now})
assert load('current-render/rendering.json')['passed'] and load('current-render-controls/rendering.json')['passed']
save('current-render-inspection.json',{'reports':['current-render/rendering.json','current-render-controls/rendering.json'],'fresh_cases':9,'inspected':['current-render/question-001.png','current-render/question-002.png','current-render/question-003.png','current-render/question-006.png','current-render-controls/question-001.png','current-render-controls/question-002.png','current-render-controls/question-003.png','render/question-015.png','render/question-017.png'],'observations':['Exact batch symbolic field displays c22 with box at row 2 column 2 and matching solution.','Radio matrices, five choices and indexed solutions readable.','Restored q139629 highlight at (3,1) and two numeric fields agree.','Relevant symbolic pair changes a23 to a32 and changes positional/value explanation; irrelevant all-ones pair keeps a23 while changing solution value to 1.','Prior radio pair independently inspected: fixed zero matrix, target moves (2,1) to (1,3); keys and solutions follow.'],'limitations':['Renderer shows preview answers; actual response grading is tested separately.','Prior UI evidence reused only after matching UI hashes. Initial render default limit six was supplemented by a separate three-control render.']})
sa=load('source-analysis.json');sa={k:sa[k] for k in ['skill','reasoning_steps','invariants','permitted_variations','source_refs','evidence_paths']}
def check(paths,details):return {'status':'passed','evidence_paths':paths,'details':details}
checks={
'source_replay':check(['source-analysis.json','current-source-replays.json','source-replay-results.json','source-comparison.json','binding-verification.json'],'All nine source cases replay unchanged, including complete banks. Missing q139629 highlight is restored from matching keys and solution; absent original keys/solutions are explicitly reconstructed.'),
'math':check(['current-math.json','independent-math.json','current-symbolic-controls.json'],'31 current records pass independent visible-coordinate checks; matching bindings permit reuse of 205 earlier checks, including solution conclusions.'),
'variety':check(['pedagogical-variation.json','boundaries.json','current-fresh-batches.json','current-delivery-analysis.json','reuse-provenance.json'],'All four response templates, five bank profiles and 55 coordinate boundaries remain supported. Fresh sampling and delivery preserve contrasting target roles.'),
'scope':check(['source-analysis.json','current-source-replays.json','current-math.json'],'Easy questions retain small-matrix visual indexing and source response workloads. Authored moderate/hard levels are outside this verdict.'),
'grading':check(['current-native-input.json','current-native-report.json','current-native-execution.json','retained-findings-review.json','author-rerun/comma/summary.json'],'274 acceptance and 500 rejection checks pass with zero unresolved outcomes. The original comma-index counterexample and retained strict regressions pass against the current native grader.'),
'rendering':check(['current-render/rendering.json','current-render-controls/rendering.json','current-render-inspection.json','current-render/question-002.png','current-render-controls/question-002.png'],'Nine fresh actual-UI cases pass diagnostics; inspected screenshots show readable matrices, highlights, answer controls and solutions. Bound earlier UI evidence is retained.'),
'packaging':check(['current-packaging.json','current-relocation-execution.json','packaging-results.json','package-integrity.json'],'Exact installed dependencies match the manifest. Deterministic runner-batch replay and relocation pass; unchanged invalid-input checks are retained. Package files did not change.'),
'decision_variation':check(['pedagogical-variation.json','variation-validation.json','current-delivery-analysis.json','current-native-report.json','current-rendered-positions.json','current-inventory-verification.json'],'Relevant and irrelevant counterfactuals pass. The retained bank-only shortcut has counterexamples. All five runner records survive filtering; both radio groups retain contrasting targets and rendered answer positions. Selection conclusions are limited to captured inventory and inspected rules.')}
result={'verdict':'accepted','summary':'All eight checks pass. The comma-index grading failure is repaired, prior regressions remain satisfied, and the exact five-record batch passes. Package unchanged; no generated stored-pool defect demonstrated.','source_analysis':sa,'checks':checks,'findings':[]}
refs=sa['evidence_paths']+[f for c in checks.values() for f in c['evidence_paths']]
assert all((R/f).is_file() and (R/f).stat().st_size for f in refs)
assert load('current-summary.json')['native_exit']==0 and load('variation-validation.json')['schema']=='passed'
save('result.json',result)
save('evidence-contract.json',{'all_eight_checks':list(checks),'all_passed_checks_have_nonempty_local_evidence':True,'pedagogical_schema':'passed','affected_inventory':'affected-inventory.json','package_unchanged':True,'result_file':'result.json','limitations':['Easy only; finite audit does not prove absence of every shortcut.','Captured inventory basis 5667; live learner histories and later inventory unavailable.','Earlier independent evidence reused with verified bindings and file provenance; changed engine behavior freshly retested.']})
(R/'session-state.md').write_text('Review complete: accepted. All eight checks pass. Result: result.json. Native grader: 274 accepted and 500 rejected expectations, zero unresolved. Nine current UI cases rendered and representative screenshots inspected. Exact batch 5/5 delivered. Pedagogical schema and all cited local paths validated. Package hashes unchanged. No database or publication writes. Affected inventory empty with captured-basis limits documented.\n')
print(json.dumps({'verdict':result['verdict'],'checks':len(checks),'package_files_unchanged':len(now),'evidence_refs':len(refs)}))
